// Daily line surf. There is no freehand stroke: each beat adds one segment,
// and curvature or a cut is what changes speed (2026-10-21). A lip asks for
// speed. A wall, or a curve off the side, ends the ride. The course is
// generated by walking one legal line and never storing that line.

import { rollAugmentOffer, type AugmentDef } from "./augment";
import { mulberry32 } from "./daily";

export const GAME_ID = "line-surf";
export const STEPS = 8;
export const LANES = 3;
export const LIP_SPEED = 2;
export const MAX_SPEED = 4;
export const ACTS = ["straight", "left", "right", "cut"] as const;

export type Act = (typeof ACTS)[number];
export type Tile = "open" | "wall" | "lip";
export type Phase = "ready" | "play" | "won" | "lost";

export interface Puzzle {
  seed: number;
  columns: Tile[][];
}

export const SURF_CUES = ["straight", "turn", "cut", "lip", "win", "lose"] as const;
export type SurfCue = (typeof SURF_CUES)[number];

export const SURF_AUGMENTS = [
  { id: "glide", tier: "silver", max: 1 },
  { id: "softCut", tier: "silver", max: 1 },
  { id: "tailwind", tier: "silver", max: 1 },
  { id: "floor", tier: "silver", max: 1 },
  { id: "lowLip", tier: "gold", max: 1 },
  { id: "skim", tier: "gold", max: 1 },
  { id: "pocket", tier: "gold", max: 1 },
  { id: "headStart", tier: "prismatic", max: 1 },
] as const satisfies readonly AugmentDef[];

export type SurfAugmentId = (typeof SURF_AUGMENTS)[number]["id"];

export interface Run {
  puzzle: Puzzle;
  phase: Phase;
  step: number;
  lane: number;
  speed: number;
  augment: SurfAugmentId | null;
  skimLeft: number;
  pocketLeft: number;
  lastAct: Act | null;
}

interface Spot {
  lane: number;
  speed: number;
}

export function createPuzzle(seed: number): Puzzle {
  const mixed = seed >>> 0;
  const rng = mulberry32(mixed ^ 0x51a70001);
  let spot: Spot = { lane: 1, speed: 2 };
  const columns: Tile[][] = [];
  for (let step = 0; step < STEPS; step += 1) {
    const tiles: Tile[] = ["open", "open", "open"];
    const act = forcedAct(spot.lane, step, rng);
    const next = moved(spot, act);
    if (!next) {
      columns.push(tiles);
      continue;
    }
    if (act === "left" || act === "right") tiles[spot.lane] = "wall";
    if (next.speed >= LIP_SPEED && rng() < 0.5) tiles[next.lane] = "lip";
    const others = [0, 1, 2].filter((lane) => lane !== next.lane && tiles[lane] === "open");
    if (others.length > 0 && rng() < 0.75) {
      const lane = others[Math.floor(rng() * others.length)] ?? 0;
      tiles[lane] = "wall";
    }
    if (tiles[next.lane] === "wall" || (tiles[next.lane] === "lip" && next.speed < LIP_SPEED)) tiles[next.lane] = "open";
    columns.push(tiles);
    spot = next;
  }
  return { seed: mixed, columns };
}

export function createRun(puzzle: Puzzle, augment: SurfAugmentId | null = null): Run {
  return {
    puzzle,
    phase: "ready",
    step: 0,
    lane: 1,
    speed: augment === "headStart" ? 3 : 2,
    augment,
    skimLeft: augment === "skim" ? 1 : 0,
    pocketLeft: augment === "pocket" ? 1 : 0,
    lastAct: null,
  };
}

export function surfOffer(seed: number): SurfAugmentId[] {
  return rollAugmentOffer(SURF_AUGMENTS, {}, seed >>> 0).offer;
}

// The result button used to rebuild today's seed. A practice wave has to be a
// different board, or "again" is the same daily course (2026-10-21).
export function freshSeed(salt: number, dailySeed: number): number {
  const next = salt >>> 0;
  const daily = dailySeed >>> 0;
  return next === daily ? (next + 1) >>> 0 : next;
}

export function begin(run: Run): Run {
  if (run.phase !== "ready") return run;
  return { ...run, phase: "play" };
}

export function ride(run: Run, act: Act): Run {
  if (run.phase !== "play") return run;
  let next = moved(run, act, run.augment);
  let skimLeft = run.skimLeft;
  let pocketLeft = run.pocketLeft;
  if (!next && run.augment === "pocket" && pocketLeft > 0 && (act === "left" || act === "right")) {
    next = { lane: run.lane, speed: Math.max(0, run.speed - 1) };
    pocketLeft -= 1;
  }
  if (!next) return { ...run, lastAct: act, phase: "lost" };
  const column = run.puzzle.columns[run.step];
  const tile = column?.[next.lane] ?? "wall";
  const lipSpeed = run.augment === "lowLip" ? 1 : LIP_SPEED;
  if (tile === "wall" && run.augment === "skim" && skimLeft > 0) {
    skimLeft -= 1;
  } else if (tile === "wall" || (tile === "lip" && next.speed < lipSpeed)) {
    return { ...run, lane: next.lane, speed: next.speed, skimLeft, pocketLeft, lastAct: act, phase: "lost" };
  }
  const step = run.step + 1;
  const movedRun = { ...run, ...next, step, skimLeft, pocketLeft, lastAct: act };
  if (step >= STEPS) return { ...movedRun, phase: "won" };
  return movedRun;
}

export function surfCue(before: Run, after: Run): SurfCue | null {
  if (before.phase !== "play" || after.phase === "ready") return null;
  if (after.phase === "won") return "win";
  if (after.phase === "lost") return "lose";
  if (after.step === before.step) return null;
  const tile = before.puzzle.columns[before.step]?.[after.lane];
  if (tile === "lip") return "lip";
  if (after.lastAct === "cut") return "cut";
  if (after.lastAct === "left" || after.lastAct === "right") return "turn";
  return "straight";
}

/** The cell the rider just left. A fall throws no spray. */
export function sprayCell(before: Run, after: Run): { step: number; lane: number } | null {
  if (before.phase !== "play" || (after.phase !== "play" && after.phase !== "won") || after.step === before.step) return null;
  return { step: before.step, lane: after.lane };
}

export function expire(run: Run): Run {
  if (run.phase !== "play") return run;
  return { ...run, phase: "lost" };
}

function forcedAct(lane: number, step: number, rng: () => number): Act {
  if (step % 3 === 2) {
    if (lane === 0) return "right";
    if (lane === 2) return "left";
    return rng() < 0.5 ? "left" : "right";
  }
  const choices: Act[] = ["straight"];
  if (lane > 0) choices.push("left");
  if (lane < LANES - 1) choices.push("right");
  return choices[Math.floor(rng() * choices.length)] ?? "straight";
}

function curveSpeed(speed: number, augment: SurfAugmentId | null): number {
  if (augment === "glide") return speed;
  if (augment === "floor") return speed <= 1 ? speed : speed - 1;
  return Math.max(0, speed - 1);
}

function moved(spot: Spot, act: Act, augment: SurfAugmentId | null = null): Spot | null {
  if (act === "straight") {
    const gain = augment === "tailwind" ? 2 : 1;
    return { lane: spot.lane, speed: Math.min(MAX_SPEED, spot.speed + gain) };
  }
  if (act === "cut") return { lane: spot.lane, speed: augment === "softCut" ? 1 : 0 };
  if (act === "left") {
    if (spot.lane === 0) return null;
    return { lane: spot.lane - 1, speed: curveSpeed(spot.speed, augment) };
  }
  if (spot.lane === LANES - 1) return null;
  return { lane: spot.lane + 1, speed: curveSpeed(spot.speed, augment) };
}
